from taf.internal.robot_typecasts import time_to_seconds, to_boolean


class UserManagementInterface(object):

    def change_local_account_state(self, account_type, enable, timeout=60):
        """Change local account state.

        :param string account_type: BtsSecurity, BtsApplication or BtsRead
        :param boolean enable: Should enable.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        enable = to_boolean(enable)
        timeout = time_to_seconds(timeout)
        assert account_type in ("BtsSecurity", "BtsApplication", "BtsRead")
        self._api_client.execute_procedure("changeLocalAccountState", {"accountType": account_type, "enable": enable}, timeout)

    def change_ssh_password(self, username, new_password, old_password, timeout=60):
        """Change SSH password.

        :param string username: Username.
        :param string new_password: New password.
        :param string old_password: Old password.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(username)
        str(new_password)
        str(old_password)

        parameters = {
            "username": username,
            "password": new_password,
            "oldUsername": username,
            "oldPassword": old_password,
        }
        self._api_client.execute_procedure("modifySshUser", parameters, timeout)

    def set_user_account(self, old_username, old_password, new_username=None, new_password=None, timeout=60):
        """Set user account.

        :param string old_username: Old username.
        :param string old_password: Old password.
        :param string new_username: New username.
        :param string new_password: New password.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        timeout = time_to_seconds(timeout)
        str(old_username)
        str(old_password)

        parameters = {
            "oldUsername": old_username,
            "oldPassword": old_password
        }

        if new_username is not None:
            str(new_username)
            parameters["username"] = new_username

        if new_password is not None:
            str(new_password)
            parameters["password"] = new_password

        self._api_client.execute_procedure("userAccountSet", parameters, timeout)

    def get_user_login_info(self, timeout=60):
        """Get user login info."""
        timeout = time_to_seconds(timeout)
        parameters = {}

        return self._api_client.execute_infomodel_request("getUserLoginInfo", parameters, timeout)
